import Foundation

let code = "\n// Self-replicating quine with evolving atmospheric fractal ASCII poetry landscape\nfunc main() {\n    // Fetch real-time atmospheric pressure (hPa) or fallback to standard pressure\n    var hpa = 1013.25\n    if let url = URL(string: \"[https://api.open-meteo.com/v1/forecast?latitude=51.5074&longitude=-0.1278&current=surface_pressure](https://api.open-meteo.com/v1/forecast?latitude=51.5074&longitude=-0.1278&current=surface_pressure)\"),\n       let data = try? Data(contentsOf: url),\n       let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any],\n       let current = json[\"current\"] as? [String: Any],\n       let pressure = current[\"surface_pressure\"] as? Double {\n        hpa = pressure\n    }\n\n    // Output Quine (Self-Replication)\n    let quineSource = \"import Foundation\\n\\nlet code = \\(String(reflecting: code))\\(code)\"\n    print(quineSource)\n    print(\"\\n\" + String(repeating: \"=\", count: 70))\n    print(\"// ATMOSPHERIC FRACTAL POETRY LANDSCAPE | Pressure: \\(hpa) hPa\")\n    print(String(repeating: \"=\", count: 70) + \"\\n\")\n\n    // Evolving Fractal Landscape Generation\n    let verses = [\n        \"whispers of dynamic air\",\n        \"barometric waves drift high\",\n        \"fractal mountains touch the mist\",\n        \"realms shaped by atmosphere\"\n    ]\n    let glyphs = Array(\" .:-=+*#%@\")\n    let rows = 20, cols = 70\n    let scale = 0.05 * (hpa / 1013.25)\n\n    for y in 0..<rows {\n        var line = \"\"\n        for x in 0..<cols {\n            let cx = Double(x - cols / 2) * scale\n            let cy = Double(y - rows / 2) * scale * 2.0\n            var zr = 0.0, zi = 0.0, iter = 0\n            let maxIter = 32\n            \n            while zr * zr + zi * zi < 4.0 && iter < maxIter {\n                let temp = zr * zr - zi * zi + cx\n                zi = 2.0 * zr * zi + cy + sin(Double(y) * 0.1)\n                zr = temp + cos(Double(x) * 0.1)\n                iter += 1\n            }\n            \n            if iter == maxIter {\n                let verse = verses[(y + x) % verses.count]\n                let charIdx = verse.index(verse.startIndex, offsetBy: (x % verse.count))\n                line.append(verse[charIdx])\n            } else {\n                line.append(glyphs[iter % glyphs.count])\n            }\n        }\n        print(line)\n    }\n}\n\nmain()\n"

print("import Foundation\n\nlet code = \(String(reflecting: code))\(code)")